import json
import re


def _strip_think(text):
    if not text:
        return ""
    return re.sub(r"<think>.*?</think>", "", str(text), flags=re.DOTALL).strip()


def _find_analyze(analyze_json):
    """从 Dify json 变量提取 analyze 返回 dict（兼容嵌套 list/dict/data 包裹）。"""
    if analyze_json is None:
        return {}
    an = analyze_json
    if isinstance(an, str):
        try:
            an = json.loads(an)
        except Exception:
            return {}
    if isinstance(an, list):
        if not an:
            return {}
        an = an[0]
    if isinstance(an, dict) and isinstance(an.get("data"), list) and an["data"]:
        an = an["data"][0]
    return an if isinstance(an, dict) else {}


def _analysis_images_md(analyze_json):
    an = _find_analyze(analyze_json)
    parts = []
    heatmap = an.get("heatmap_png_base64")
    waveform = an.get("waveform_png_base64")
    if heatmap:
        parts.append(f"\n\n![稳态声压场热力图](data:image/png;base64,{heatmap})")
    if waveform:
        label = "点传感器时域声压曲线" if an.get("waveform_kind") == "sensor_time" else "声压空间剖面"
        parts.append(f"\n\n![{label}](data:image/png;base64,{waveform})")
    return "".join(parts)


def main(mcp_json, review_text, explanation, analyze_json):
    data = mcp_json
    if isinstance(data, list) and len(data) > 0:
        data = data[0]
    if isinstance(data, str):
        try:
            data = json.loads(data)
        except Exception:
            return {"result": str(data)}
    if not isinstance(data, dict):
        return {"result": str(data)}

    report = data.get("report", "")
    parts = []
    if report:
        parts.append(report)

    verdict = _strip_think(review_text).lower()
    if verdict and verdict != "pass":
        parts.append(f"\n\n> ⚠️ **审查结论：{verdict}**（结果疑似异常，建议检查参数后重试）")

    expl = _strip_think(explanation)
    if expl:
        parts.append(f"\n\n---\n\n## 🧠 物理解读\n\n{expl}")

    result = "\n".join(p for p in parts if p)
    result += _analysis_images_md(analyze_json)
    if result:
        return {"result": result}
    return {"result": json.dumps(data, ensure_ascii=False, indent=2)}

