def main(parameters_json: str, scenario_type: str="", original_query: str="") -> dict:
    """No scenario guessing or prose parsing; invalid extraction bypasses learning."""
    closed=dict(ready=False,scenario_type="",candidate_parameters_json="{}",
                retrieval_parameters_json="{}",reason="invalid_skill_parameters")
    try:
        if original_query is None or type(parameters_json) is not str or len(parameters_json.encode())>32768:
            return closed
        # DeepSeek's configured transport may prepend one closed reasoning block.
        # Accept no prose, repeated blocks, fences or trailing JSON outside it.
        text=parameters_json.strip()
        if text.startswith("<think>"):
            end=text.find("</think>")
            if end<0 or "<think>" in text[7:end]:return closed
            text=text[end+8:].strip()
        elif len(parameters_json.encode())>4096:return closed
        if len(text.encode())>4096:return closed
        params=json.loads(text,object_pairs_hook=_unique,parse_constant=_invalid)
        if type(params) is not dict:return closed
        description=params.pop("description",None)
        if description is not None and (type(description) is not str or len(description.encode())>512):
            return closed
        embedded=params.pop("scenario_type",None)
        if embedded is not None:
            if scenario_type and scenario_type!=embedded:return closed
            scenario_type=embedded
        periodic=PERIODIC_PARAMETERS.get(params.get("source_geometry"))
        if periodic is not None:
            # Fixed periodic reuse requires the user's complete explicit declaration.
            if type(original_query)is not str or not original_query.strip():return closed
            # Unit aliases only: never fill missing fields from the catalog.
            normalized={}
            for key,value in params.items():
                target=ALIASES.get(key,key)
                if target in normalized:
                    if not original_query or normalized[target]!=value:return closed
                    continue
                normalized[target]=value
            # The old extractor schema declares a nonexistent frequency as null.
            # Only this explicit null is ignored for modal initial pressure.
            if normalized.get("frequency_hz","absent") is None:normalized.pop("frequency_hz")
            if original_query:
                # Bind structured user declarations, never fill from a skill catalog.
                # Only one complete final JSON object is accepted; prose cannot supply defaults.
                if type(original_query) is not str or len(original_query.encode())>8192:return closed
                start=original_query.find("{")
                if start<0:return closed
                declared=json.loads(original_query[start:],object_pairs_hook=_unique,parse_constant=_invalid)
                if type(declared) is not dict or len(original_query[start:].encode())>4096:return closed
                declared.pop("scenario_type",None)
                if set(declared)!=set(periodic):return closed
                if any(key not in declared or value!=declared[key] for key,value in normalized.items()):return closed
                normalized=declared
            if scenario_type!="initial_pressure_2d" or json.dumps(normalized,sort_keys=True,allow_nan=False)!=json.dumps(periodic,sort_keys=True,allow_nan=False):return closed
            text=json.dumps(periodic,sort_keys=True,separators=(",",":"),allow_nan=False)
            return dict(ready=True,scenario_type=scenario_type,candidate_parameters_json=text,retrieval_parameters_json=text,reason="declared_exact_periodic_parameters")
        if type(scenario_type) is not str or scenario_type not in SCENARIOS or not set(params)<=ALLOWED:
            return closed
        initial = scenario_type=="initial_pressure_2d"
        required={"sound_speed","domain_N","domain_dx","pml_size","solver_mode","medium_type"}
        required |= {"source_kind","initial_pressure_pa","initial_sigma_m","initial_velocity"} if initial else {"source_frequency"}
        if initial and (params.get("source_kind")!="gaussian_initial_pressure" or params.get("initial_velocity")!="zero"
                        or "source_frequency" in params):
            return closed
        if "source_kind" in params and params["source_kind"] not in {"continuous_sinusoid","gaussian_initial_pressure"}:
            return closed
        if not initial and params.get("source_kind")=="gaussian_initial_pressure":
